<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { descargarArchivoAccion, detallarAccion, eliminarArchivoAccion, finalizarAccion, listarAcciones, subirArchivoAccion, votarAccion } from '../services/acciones'
import type { AccionDirectorio, AccionTipo } from '../interfaces/acciones.interface'
const props=defineProps<{tipo:AccionTipo;title:string;description:string;color?:string}>(),filters=reactive({criterio:'',estado:'',page:1}),items=ref<AccionDirectorio[]>([]),pagination=reactive({current:1,last:1,total:0}),loading=ref(false),processing=ref(false),error=ref(''),success=ref(''),detail=ref<AccionDirectorio|null>(null),voteOpen=ref(false),finishOpen=ref(false),approved=ref(true),comment=ref(''),answer=ref(''),file=ref<File|null>(null)
const plural=computed(()=>props.tipo==='disposicion'?'disposiciones':`${props.tipo}s`)
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarAcciones(props.tipo,filters);items.value=r.data;Object.assign(pagination,{current:r.current_page,last:r.last_page,total:r.total})}catch(cause){error.value=cause instanceof Error?cause.message:`No se pudieron cargar ${plural.value}.`}finally{loading.value=false}}
async function show(i:AccionDirectorio){processing.value=true;try{detail.value=await detallarAccion(props.tipo,i.id)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo cargar el detalle.'}finally{processing.value=false}}
function openVote(){approved.value=true;comment.value='';voteOpen.value=true}
async function vote(){if(!detail.value)return;if(!approved.value&&!comment.value.trim()){error.value='El comentario es obligatorio al desaprobar.';return}processing.value=true;try{await votarAccion(props.tipo,detail.value.id,{aprobado:approved.value,comentario:comment.value});success.value='Visto bueno registrado.';voteOpen.value=false;detail.value=await detallarAccion(props.tipo,detail.value.id);await load(filters.page)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo registrar el voto.'}finally{processing.value=false}}
async function upload(){if(!detail.value||!file.value)return;processing.value=true;try{await subirArchivoAccion(props.tipo,detail.value.id,file.value);success.value='Archivo cargado. Los vistos buenos anteriores fueron reiniciados.';file.value=null;detail.value=await detallarAccion(props.tipo,detail.value.id);await load(filters.page)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo cargar el archivo.'}finally{processing.value=false}}
async function removeFile(id:number){if(!detail.value||!confirm('¿Eliminar este archivo?'))return;try{await eliminarArchivoAccion(props.tipo,detail.value.id,id);detail.value=await detallarAccion(props.tipo,detail.value.id);await load(filters.page)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo eliminar el archivo.'}}
async function finish(){if(!detail.value||answer.value.trim().length<5){error.value='La respuesta debe tener al menos 5 caracteres.';return}processing.value=true;try{await finalizarAccion(props.tipo,detail.value.id,answer.value);success.value=`${props.title.slice(0,-1)} atendido correctamente.`;finishOpen.value=false;detail.value=null;await load(filters.page)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo finalizar. Verifique que exista al menos un archivo.'}finally{processing.value=false}}
function date(v?:string|null){return v?new Intl.DateTimeFormat('es-PE',{dateStyle:'medium'}).format(new Date(`${v.slice(0,10)}T00:00:00`)):'Sin plazo'}
onMounted(()=>load())
</script>
<template><div class="actions-page" :style="{'--accent':color||'#7257c8'}"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/institucional">Institucional</RouterLink> / <RouterLink to="/modulos/institucional/directorio">Directorio</RouterLink> / {{title}}</nav><header class="hero"><div class="mark">AU</div><div><small>Directorio</small><h1>{{title}}</h1><p>{{description}}</p></div><strong>{{pagination.total}} registros</strong></header><div v-if="success" class="flash">✓ {{success}}<button @click="success=''">×</button></div><div v-if="error" class="flash error">{{error}}<button @click="error=''">×</button></div><form class="filters" @submit.prevent="load()"><label><span>Criterio</span><input v-model.trim="filters.criterio" placeholder="Sesión, agenda o descripción"></label><label><span>Estado</span><select v-model="filters.estado"><option value="">Todos</option><option value="pendiente">Pendientes</option><option value="atendido">Atendidos</option></select></label><button>Buscar</button><button type="button" class="clear" @click="filters.criterio='';filters.estado='';load()">Limpiar</button></form><div v-if="loading" class="notice">Cargando {{title.toLowerCase()}}…</div><div v-else-if="!items.length" class="notice"><b>No se encontraron registros</b><span>Modifica los filtros de búsqueda.</span></div><section v-else class="cards"><article v-for="i in items" :key="i.id" :class="{done:i.fecha_atencion}"><header><div class="icon">{{tipo==='pedido'?'PE':tipo==='acuerdo'?'AC':'DI'}}</div><div><small>Sesión N.° {{i.sesion.numeracion}} · {{date(i.sesion.fecha_sesion)}}</small><h2>{{i.agenda?.punto_agenda||title.slice(0,-1)}}</h2></div><em>{{i.fecha_atencion?'Atendido':'Pendiente'}}</em></header><div class="body"><p>{{i.descripcion}}</p><dl><div><dt>{{tipo==='pedido'?'Solicitado por':'Responsable'}}</dt><dd>{{i.director||i.responsable||'—'}}</dd></div><div><dt>Plazo</dt><dd>{{date(i.fecha)}}</dd></div><div><dt>Archivos</dt><dd>{{i.archivos.length}}</dd></div><div><dt>Vistos buenos</dt><dd>{{i.votos_aprobados||0}} / {{i.total_directores||0}}</dd></div></dl><div class="progress"><i :style="{width:`${Math.min(100,((i.votos_aprobados||0)/(i.total_directores||1))*100)}%`}"></i></div></div><footer><button @click="show(i)">{{i.fecha_atencion?'Detallar':'Atender'}}</button></footer></article></section><footer v-if="pagination.last>1" class="pagination"><button :disabled="pagination.current===1" @click="load(pagination.current-1)">Anterior</button><span>Página {{pagination.current}} de {{pagination.last}}</span><button :disabled="pagination.current===pagination.last" @click="load(pagination.current+1)">Siguiente</button></footer><div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>Sesión N.° {{detail.sesion.numeracion}}</small><h2>{{detail.agenda?.punto_agenda||title.slice(0,-1)}}</h2></div><button @click="detail=null">×</button></header><div class="detail-body"><p class="description">{{detail.descripcion}}</p><div class="metadata"><span><small>Responsable</small><b>{{detail.director||detail.responsable||'—'}}</b></span><span><small>Plazo</small><b>{{date(detail.fecha)}}</b></span><span><small>Estado</small><b>{{detail.fecha_atencion?'Atendido':'Pendiente'}}</b></span></div><section><header><h3>Archivos de atención</h3><span>{{detail.archivos.length}}</span></header><div v-if="!detail.fecha_atencion" class="upload"><input type="file" @change="file=($event.target as HTMLInputElement).files?.[0]||null"><button :disabled="!file||processing" @click="upload">Subir archivo</button></div><ul><li v-for="a in detail.archivos" :key="a.id"><button class="file-name" @click="descargarArchivoAccion(tipo,detail!.id,a)">{{a.archivo}}</button><small>{{a.usuario||''}}</small><button v-if="!detail.fecha_atencion" class="remove" @click="removeFile(a.id)">×</button></li></ul></section><section><header><h3>Vistos buenos</h3><span>{{detail.votos_aprobados||0}} / {{detail.total_directores||0}}</span></header><ul class="votes"><li v-for="v in detail.votos" :key="v.id"><b>{{v.usuario}}</b><span :class="v.aprobado?'yes':'no'">{{v.aprobado?'Aprobado':'Desaprobado'}}</span><p v-if="v.comentario">{{v.comentario}}</p></li></ul><button v-if="detail.puede_votar&&!detail.ya_voto&&!detail.fecha_atencion" class="vote" @click="openVote">Registrar visto bueno</button></section><section v-if="detail.atencion" class="answer"><h3>Respuesta de atención</h3><p>{{detail.atencion}}</p><small>{{date(detail.fecha_atencion)}}</small></section><footer v-if="!detail.fecha_atencion&&detail.puede_atender"><button class="finish" :disabled="!detail.archivos.length" @click="answer='';finishOpen=true">Atender y cerrar</button></footer></div></section></div><div v-if="voteOpen" class="backdrop"><section class="modal small"><header><div><small>Participación del Directorio</small><h2>Registrar visto bueno</h2></div><button @click="voteOpen=false">×</button></header><form @submit.prevent="vote"><div class="vote-choice"><label><input v-model="approved" type="radio" :value="true"> Aprobar</label><label><input v-model="approved" type="radio" :value="false"> Desaprobar</label></div><label><span>Comentario {{approved?'opcional':'*'}}</span><textarea v-model.trim="comment" rows="4"></textarea></label><footer><button type="button" class="clear" @click="voteOpen=false">Cancelar</button><button :disabled="processing">Confirmar</button></footer></form></section></div><div v-if="finishOpen" class="backdrop"><section class="modal small"><header><div><small>Cierre de atención</small><h2>Atender {{title.slice(0,-1).toLowerCase()}}</h2></div><button @click="finishOpen=false">×</button></header><form @submit.prevent="finish"><label><span>Respuesta *</span><textarea v-model.trim="answer" rows="5" placeholder="Detalle la atención realizada"></textarea></label><footer><button type="button" class="clear" @click="finishOpen=false">Cancelar</button><button :disabled="processing">Atender y cerrar</button></footer></form></section></div></div></template>
<style scoped>
