ound:#fff}.cards article.done{border-top-color:#278763}.cards article>header{padding:14px;display:flex;align-items:center;gap:9px;border-bottom:1px solid #eeeaf5}.icon{width:38px;height:38px;display:grid;place-items:center;border-radius:8px;color:var(--accent);background:#eeeafa;font-size:.58rem;font-weight:700}.cards h2{margin:2px 0;font-size:.74rem}.cards header small{color:#89959b;font-size:.54rem}.cards header em{margin-left:auto;padding:4px 6px;border-radius:12px;color:#624ba7;background:#eeeafa;font-size:.51rem;font-style:normal}.done header em{color:#247054;background:#e5f6ee}.body{padding:14px}.body>p{min-height:45px;margin:0 0 8px;font-size:.65rem;line-height:1.45}.body dl{margin:0}.body dl>div{padding:5px 0;display:flex;justify-content:space-between;border-top:1px solid #efedf4;font-size:.57rem}.body dd{margin:0;text-align:right}.progress{height:4px;margin-top:9px;border-radius:4px;background:#ebeef0}.progress i{display:block;height:100%;border-radius:4px;background:var(--accent)}.cards article>footer{padding:0 14px 14px}.cards footer button{width:100%}.pagination{padding:18px;display:flex;justify-content:center;align-items:center;gap:12px;font-size:.64rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,760px);max-height:calc(100vh - 40px);overflow:auto;border-radius:12px;background:#fff}.modal.small{max-width:470px}.modal>header{padding:18px 20px;display:flex;border-bottom:1px solid #e5eaed}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.detail-body{padding:20px}.description{padding:12px;border-radius:7px;background:#f6f7f9;font-size:.7rem}.metadata{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.metadata span{padding:9px;border:1px solid #e4e8eb;border-radius:7px}.metadata small,.metadata b{display:block;font-size:.58rem}.metadata small{color:#89959b}.detail-body section{margin-top:13px;padding:13px;border:1px solid #e3e8eb;border-radius:8px}.detail-body section>header{display:flex}.detail-body h3{margin:0;font-size:.7rem}.detail-body section>header span{margin-left:auto;font-size:.58rem}.upload{margin-top:10px;display:flex;gap:6px}.detail-body ul{margin:9px 0 0;padding:0;list-style:none}.detail-body li{padding:7px 0;border-top:1px solid #edf0f2;font-size:.59rem}.file-name{border:0;color:var(--accent);background:none;font-weight:600}.detail-body li small{color:#89959b}.remove{float:right;border:0;color:#b24646;background:none}.votes li{display:grid;grid-template-columns:1fr auto}.votes li p{grid-column:1/-1;margin:3px 0;color:#737f85}.votes .yes{color:#247054}.votes .no{color:#a13f43}.vote{margin-top:10px}.answer{color:#266b51;background:#eff9f4}.answer p{font-size:.63rem}.detail-body>footer{margin-top:15px;text-align:right}.finish{background:#278763!important;border-color:#278763!important}.modal>form{padding:20px}.vote-choice{display:flex;gap:20px;margin-bottom:14px}.vote-choice label{font-size:.67rem}.vote-choice input{width:auto;height:auto}.modal form footer{margin-top:15px;display:flex;justify-content:flex-end;gap:7px}@media(max-width:950px){.cards{grid-template-columns:1fr 1fr}}@media(max-width:620px){.hero{flex-wrap:wrap}.hero>strong{margin:0}.cards,.filters,.metadata{grid-template-columns:1fr}}
</style>
